from typing import List

def maxProduct(nums: List[int], k: int, limit: int) -> int:
    # dp[(sum, length_parity)] = set of products
    dp = {}
    for x in nums:
        new_states = {}
        if x <= limit:
            new_states[(x, 1)] = {x}

        for (s, parity), prods in dp.items():
            # If current length is odd (1), next element is at index 1 (even position) -> subtract
            # Wait, the example [1,2,3] sum is 1-2+3. Indices are 0,1,2.
            # So: Index 0 is +, Index 1 is -, Index 2 is +...
            # If parity == 1 (current length), next index is 1 (even) -> subtract x
            new_sum = s - x if parity == 1 else s + x
            new_parity = (parity + 1) % 2
            if (new_sum, new_parity) not in new_states: new_states[(new_sum, new_parity)] = set()
            for p in prods:
                np = p * x
                if np <= limit:
                    new_states[(new_sum, new_parity)].add(np)

        for state, prods in new_states.items():
            if state not in dp: dp[state] = set()
            dp[state].update(prods)

    res = -1
    for (s, parity), prods in dp.items():
        if s == k:
            if prods: res = max(res, max(prods))
    return res
```

這是一個典型的動態規劃 (Dynamic Programming) 問題。由於 `limit` 較小（$\le 5000$），我們可以將「目前乘積」作為 DP 的狀態之一。

為了處理交替和（Alternating Sum），我們需要知道 subsequence 當前元素的索引是**偶數位**還是**奇數位**。

```python
from typing import List

def maxProduct(nums: List[int], k: int, limit: int) -> int:
    # dp[(current_sum, current_product)] = True (or just use a set of products for each sum)
    # 因為我們要找最大乘積，且 limit 很小，用字典存每個 sum 對應的可能 product 集合較有效率
    # dp[alternating_sum] = {set of possible products}
    # 但因為我們需要區分「下一個數字是加還是減」，我們可以用兩個 dictionary
    # even_dp: 下一個數字會被當作偶數位 (正號) 的狀態
    # odd_dp:  下一個數字會被當作奇數位 (負號) 的狀態

    # 狀態定義：dp[current_sum][current_product] = True
    # 為了優化，我們用字典：dp[alternating_sum] = set(products)
    # 因為 limit 很小，每個 sum 對應的 product 數量不會太多

    # 我們需要區分「當前 subsequence 長度是偶數還是奇數」來決定正負號
    # dp[parity][current_sum] = set of products
    # parity 0: 下一個加入的數字會是偶數位 (正)
    # parity 1: 下一個加入的數字會是奇數位 (負)

    dp = [{} for _ in range(2)] # dp[0] 為偶數位開始, dp[1] 為奇數位開始
    for i in range(2):
        dp[i] = {} # 使用 dict 結構：dp[parity][sum] = set of products

    # 初始化：空 subsequence 的狀態 (我們不直接放，由第一個數字進入)
    # 為了處理「非空」的要求，我們在迴圈中處理第一個數字的加入

    ans = -1

    for x in nums:
        # 狀況 1: 這個 x 作為整個 subsequence 的第一個元素 (必定是偶數位/正號)
        new_sum = x
        if abs(new_sum) <= 100000: # 基本範圍檢查，其實 k 就是範圍
            if new_sum not in dp[0]: dp[0][new_sum] = set()
            dp[0][new_sum].add(x)

        # 狀況 2: 這個 x 接在現有的 subsequence 後面
        # 從偶數位狀態轉到奇數位 (x 會變成負號)
        for s, products in dp[0].items():
            next_s = s - x
            if abs(next_s) <= 100000:
                if next_s not in dp[1]: dp[1][next_s] = set()
                for p in products:
                    new_p = p * x
                    if new_p <= limit:
                        dp[1][next_s].add(new_p)

        # 從奇數位狀態轉到偶數位 (x 會變成正號)
        # 注意：這裡要用暫存，避免在同一個 nums[i] 迴圈內重複處理同一元素
        # 但因為我們是從 dp[0] 轉到 dp[1]，且邏輯上 x 的位置是固定的，
        # 我們需要先計算出新的狀態再更新。

        # 修正：為了避免同一個數字被重複使用，我們應該用暫存或倒序處理
        # 但這裡每個 nums[i] 只選一次，所以標準做法是從舊的 dp 產生新的結果

    # 上述邏輯在處理「連續」與「非連續」時會混淆。正確做法如下：
    # 用一個 map 儲存 (parity, current_sum) -> set of products
    states = {} # (parity, current_sum) -> set of products

    for x in nums:
        new_states = {}
        # 情況 A: x 是第一個元素
        # 它處於偶數位 (index 0)，所以是 +x
        s1 = x
        if s1 not in new_states.get((0, s1), set()): # 這裡邏輯需要微調
            pass # 重寫下方更清晰的結構

    # --- 正確且簡潔的 DP 實作 ---
    # dp[parity][sum] = set of products
    # parity 0: 下一個加入會是正號 (目前長度為偶數)
    # parity 1: 下一個加入會是負號 (目前長度為奇數)
    dp = [{} for _ in range(2)]

    for x in nums:
        # 更新狀態的暫存，避免同一次迴圈重複計算同一個數字
        updates = []

        # 1. 作為第一個元素加入 (變成長度 1, 下一個是負號)
        updates.append((1, x, x)) 

        # 2. 接在長度為奇數的 subsequence 後面 (x 變正號，變成長度偶數)
        for s, prods in dp[1].items():
            new_s = s + x
            for p in prods:
                new_p = p * x
                if new_p <= limit:
                    updates.append((0, new_s, new_p))

        # 3. 接在長度為偶數的 subsequence 後面 (x 變負號，變成長度奇數)
        for s, prods in dp[0].items():
            new_s = s - x
            for p in prods:
                new_p = p * x
                if new_p <= limit:
                    updates.append((1, new_s, new_p))

        # 執行更新
        for parity, s, p in updates:
            if s not in dp[parity]:
                dp[parity][s] = set()
            dp[parity][s].add(p)

    res = -1
    # 檢查所有符合 k 的狀態 (不論目前長度是奇還是偶)
    for parity in range(2):
        if k in dp[parity]:
            for p in dp[parity][k]:
                res = max(res, p)

    return res

# 由於上述邏輯在處理「子序列」時，如果直接更新 dp 會變成「連續子數列」。
# 正確的子序列 DP 應該是：每個 x 可以選或不選。
# 下面是修正後的版本：

def maxProduct(nums: List[int], k: int, limit: int) -> int:
    # dp[parity][current_sum] = set of products
    # parity 0: 下一個數字加入會被當作偶數位 (正號)
    # parity 1: 下一個數字加入會被當作奇數位 (負號)
    dp = [{} for _ in range(2)]

    for x in nums:
        new_updates = []
        # 選取 x 作為第一個元素 (變成長度1，下一個是負號)
        new_updates.append((1, x, x))

        # 若選取 x 接在現有 subsequence 後面
        for parity in range(2):
            for s, prods in dp[parity].items():
                if parity == 0: # 目前長度為偶數，x 會是負號 (奇數位)
                    new_s = s - x
                    for p in prods:
                        if p * x <= limit:
                            new_updates.append((1, new_s, p * x))
                else: # 目前長度為奇數，x 會是正號 (偶數位)
                    new_s = s + x
                    for p in prods:
                        if p * x <= limit:
                            new_updates.append((0, new_s, p * x))

        # 為了不重複計算同一個數字，我們必須將 updates 加入到 dp
        # 但子序列允許「不選」當前數字，所以原本的 dp 就保留了「不選 x」的情況
        for parity, s, p in new_updates:
            if s not in dp[parity]:
                dp[parity][s] = set()
            dp[parity][s].add(p)

    ans = -1
    for p_idx in range(2):
        if k in dp[p_idx]:
            for val in dp[p_idx][k]:
                ans = max(ans, val)
    return ans
```

```python
from typing import List

def maxProduct(nums: List[int], k: int, limit: int) -> int:
    # dp[(current_alternating_sum, current_product)] = True (or just use a set of products)
    # However, since we need to maximize product and the range of sums/products is small, 
    # we can use a dictionary where keys are alternating sums and values are sets of possible products.
    # But because the number of subsequences can be large, let's optimize:
    # dp[current_sum] = set of possible products

    # State representation:
    # We need to know the index in the subsequence (even or odd) to determine the sign of the sum.
    # Let dp[i][current_sum] be a set of possible products using a subsequence from first i elements 
    # where the next element will be at an even index (relative to the start of that subsequence).
    # Wait, the definition is: alternating sum = nums[0] - nums[1] + nums[2] ...
    # This means if we pick an element, it's "even" if it's the 1st, 3rd... picked.
    # If it's "odd", it's the 2nd, 4th... picked.

    # dp[sum] = set of products where the next element to be added will be at an EVEN index (added)
    # dp_even[s] stores products for subsequences ending in an ODD position (so next is even: +val)
    # dp_odd[s] stores products for subsequences ending in an EVEN position (so next is odd: -val)

    # Let's simplify: 
    # dp[0][sum] = set of products of subsequences with current alternating sum 'sum'
    # where the NEXT element picked will be added (index 0, 2, 4...).
    # dp[1][sum] = set of products of subsequences where the NEXT element picked will be subtracted (index 1, 3, 5...).

    # Because we only care about products <= limit:
    dp_even = {} # sum -> set of products (next is even, i.e., +)
    dp_odd = {}  # sum -> set of products (next is odd, i.e., -)

    # To handle the "non-empty" constraint and the fact that the first element is always added:
    # A subsequence starting with nums[i] has sum = nums[i]. Its next element will be at index 1 (odd).

    for x in nums:
        new_dp_even = {}
        new_dp_odd = {}

        # Option 1: Start a new subsequence with x
        # It's at index 0, so sum is x. Next position is 1 (odd).
        if x <= limit:
            dp_odd[x] = dp_odd.get(x, set()) | {x}

        # Option 2: Extend existing subsequences
        # If we extend a subsequence that was at an even index (next is odd):
        # new_sum = old_sum - x
        for s, products in dp_even.items():
            new_s = s - x
            for p in products:
                if p * x <= limit:
                    new_dp_odd[new_s] = new_dp_odd.get(new_s, set()) | {p * x}

        # If we extend a subsequence that was at an odd index (next is even):
        # new_sum = old_sum + x
        for s, products in dp_odd.items():
            new_s = s + x
            for p in products:
                if p * x <= limit:
                    new_dp_even[new_s] = new_dp_even.get(new_s, set()) | {p * x}

        # Merge new updates into the main dp tables
        # This is tricky because we can't update while iterating. 
        # But since we only care about the final result and any element can be part of a subsequence:
        # Actually, standard DP for subsequences usually processes one item at a time.
        # Let's refine:

    # Correct logic for "subsequence" (elements don't have to be contiguous):
    # dp[sum][parity] = set of products
    # parity 0: next element will be added (+)
    # parity 1: next element will be subtracted (-)

    dp = [{} for _ in range(2)] # dp[0] is sums where next is +, dp[1] is sums where next is -
    # Wait, the standard way to do "subsequence" DP is:
    # For each num x in nums:
    #   Update all existing states.

    dp = [{} for _ in range(2)] 
    # dp[0][s] -> set of products where next element picked will be added (index 0, 2...)
    # dp[1][s] -> set of products where next element picked will be subtracted (index 1, 3...)

    for x in nums:
        # To avoid using the same element multiple times in one subsequence:
        next_dp = [{} for _ in range(2)]

        # Case A: Start a new subsequence with x. It's at index 0 (even). Next is odd.
        if x <= limit:
            next_dp[1][x] = next_dp[1].get(x, set()) | {x}

        # Case B: Append x to a subsequence that currently ends at an even index (so x is odd)
        for s, products in dp[0].items():
            new_s = s - x
            for p in products:
                if p * x <= limit:
                    next_dp[1][new_s] = next_dp[1].get(new_s, set()) | {p * x}

        # Case C: Append x to a subsequence that currently ends at an odd index (so x is even)
        for s, products in dp[1].items():
            new_s = s + x
            for p in products:
                if p * x <= limit:
                    next_dp[0][new_s] = next_dp[0].get(new_s, set()) | {p * x}

        # Merge updates back to dp
        for i in range(2):
            for s, products in next_dp[i].items():
                dp[i][s] = dp[i].get(s, set()) | products

    ans = -1
    # The result can be in either state (subsequence ending at even or odd index)
    # Actually, the sum 'k' must match.
    for i in range(2):
        if k in dp[i]:
            for p in dp[i][k]:
                if p <= limit:
                    ans = max(ans, p)

    return ans

