def countWinningSequences(s: str) -> int:
    MOD = 10**9 + 7
    n = len(s)
    # dp[i][last_move][score_diff]
    # score_diff ranges from -n to n, offset by n.
    # last_move: 0=F, 1=W, 2=E
    dp = [[0] * (2 * n + 1) for _ in range(3)]

    # Initial round
    for b_move in range(3):
        score = 0
        a_move = s[0]
        if a_move == 'F': # Alice Fire
            if b_move == 'E': score -= 1 # Bob Earth vs Alice Fire (Alice gets point)
            elif b_move == 'W': score += 1 # Bob Water vs Alice Fire (Bob gets point)
        elif a_move == 'W': # Alice Water
            if b_move == 'F': score += 1 # Bob Fire vs Alice Water (Bob gets point)
            elif b_move == 'E': score -= 1 # Bob Earth vs Alice Water (Alice gets point)
        elif a_move == 'E': # Alice Earth
            if b_move == 'W': score += 1 # Bob Water vs Alice Earth (Bob gets point)
            elif b_move == 'F': score -= 1 # Bob Fire vs Alice Earth (Alice gets point)

        dp[b_move][score + n] = (dp[b_move][score + n] + 1) % MOD

    for i in range(1, n):
        new_dp = [[0] * (2 * n + 1) for _ in range(3)]
        a_move = s[i]
        for last_b in range(3):
            for diff in range(-n, n + 1):
                count = dp[last_b][diff + n]
                if count == 0:
                    continue
                for curr_b in range(3):
                    if curr_b == last_b:
                        continue

                    score = 0
                    if a_move == 'F':
                        if curr_b == 'E': score -= 1
                        elif curr_b == 'W': score += 1
                    elif a_move == 'W':
                        if curr_b == 'F': score += 1
                        elif curr_b == 'E': score -= 1
                    elif a_move == 'E':
                        if curr_b == 'W': score += 1
                        elif curr_b == 'F': score -= 1

                    new_diff = diff + score
                    if -n <= new_diff <= n:
                        new_dp[curr_b][new_diff + n] = (new_dp[curr_b][new_diff + n] + count) % MOD
        dp = new_dp

    ans = 0
    for b_move in range(3):
        for diff in range(1, n + 1):
            ans = (ans + dp[b_move][diff + n]) % MOD

    return ans
