            if b_move == 2: return -1 # Bob Earth vs Alice Water -> Alice +1 (Bob -1)
        elif a_move == 2: # Alice Earth
            if b_move == 1: return 1  # Bob Water vs Alice Earth -> Bob +1
            if b_move == 0: return -1 # Bob Fire vs Alice Earth -> Alice +1 (Bob -1)
        return 0

    a0 = move_map[s[0]]
    for b in range(3):
        score = get_score(a0, b)
        dp[b][score] = (dp[b].get(score, 0) + 1) % MOD

    for i in range(1, n):
        new_dp = [collections.defaultdict(int) for _ in range(3)]
        a = move_map[s[i]]
        for prev_b in range(3):
            current_round_dp = dp[prev_b]
            if not current_round_dp:
                continue
            for diff, count in current_round_dp.items():
                for curr_b in range(3):
                    if curr_b == prev_b:
                        continue
                    score = get_score(a, curr_b)
                    new_diff = diff + score
                    new_dp[curr_b][new_diff] = (new_dp[curr_b].get(new_diff, 0) + count) % MOD
        dp = new_dp

    ans = 0
    for b in range(3):
        for diff, count in dp[b].items():
            if diff > 0:
                ans = (ans + count) % MOD
    return ans
