import math

def minCostGoodCaption(caption: str) -> str:
    n = len(caption)
    if n < 3:
        return ""

    inf = float('inf')

    def get_dist(char_code, target_code):
        return abs(char_code - target_code)

    # f[i][c]: min cost for suffix i...n-1 where index i is the start of a block of char c (length >= 3).
    # g[i][c]: min cost for suffix i...n-1 where we are at index i and it's part of a block of char c which already has length >= 3.
    f = [[inf] * 26 for _ in range(n + 1)]
    g = [[inf] * 26 for _ in range(n + 1)]

    for c in range(26):
        g[n][c] = 0

    # Precompute min_f_not_d values to speed up transitions
    min_f = [inf] * (n + 1)
    min_f2 = [inf] * (n + 1) # second min for f

    for i in range(n - 1, -1, -1):
        # Calculate min_f and its second best to handle d != c constraint efficiently
        m1, m2 = inf, inf
        for c in range(26):
            if f[i][c] < m1:
                m2 = m1
                m1 = f[i][c]
            elif f[i][c] < m2:
                m2 = f[i][c]
        min_f[i] = m1
        min_f2[i] = m2

        for c in range(26):
            # g[i][c]: at index i, we are already in a block of char c (length >= 3)
            res_g = inf
            if i + 1 <= n:
                res_g = get_dist(ord(caption[i]) - ord('a'), c) + g[i+1][c]

            for d in range(26):
                if d != c and i + 3 <= n:
                    cost_d = sum(get_dist(ord(caption[k]) - ord('a'), d) for k in range(i, i+3))
                    best_after = inf
                    if i + 3 == n:
                        best_after = 0
                    else:
                        # best_after is min_{e != d} f[i+3][e]
                        best_after = min_f[i+3] if min_f[i+3] != f[i+3][d] else min_f2[i+3]
                    res_g = min(res_g, cost_d + best_after)
            g[i][c] = res_g

            # f[i][c]: at index i, we start a block of char c (length >= 3)
            if i + 3 <= n:
                cost_c = sum(get_dist(ord(caption[k]) - ord('a'), c) for k in range(i, i+3))
                best_after = inf
                if i + 3 == n:
                    best_after = 0
                else:
                    # After three c's at i, i+1, i+2, we are at index i+3.
                    # It can be a continuation of block c (g[i+3][c]) OR a new block e != c (f[i+3][e]).
                    best_after = min(g[i+3][c], min_f[i+3] if min_f[i+3] != f[i+3][c] else min_f2[i+3])
                f[i][c] = cost_c + best_after

    min_total = inf
    for c in range(26):
        min_total = min(min_total, f[0][c])

    if min_total == inf: 
        return ""

    ans = []
    curr_c = -1
    curr_len = 0
    current_cost = 0

    for c in range(26):
        if f[0][c] == min_total:
            curr_c = c
            break

    ans.append(chr(ord('a') + curr_c))
    current_cost += get_dist(ord(caption[0]) - ord('a'), curr_c)
    curr_len = 1

    for i in range(1, n):
        if curr_len < 3:
            ans.append(chr(ord('a') + curr_c))
            current_cost += get_dist(ord(caption[i]) - ord('a'), curr_c)
            curr_len += 1
        else:
            found = False
            # Try continuing current block
            if i + 1 <= n and current_cost + get_dist(ord(caption[i]) - ord('a'), curr_c) + g[i+1][curr_c] == min_total:
                ans.append(chr(ord('a') + curr_c))
                current_cost += get_dist(ord(caption[i]) - ord('a'), curr_c)
                curr_len += 1
                found = True

            if not found:
                for d in range(26):
                    if d == curr_c: continue
                    if i + 3 <= n:
                        cost_d = sum(get_dist(ord(caption[k]) - ord('a'), d) for k in range(i, i+3))
                        best_after = inf
                        if i + 3 == n: best_after = 0
                        else:
                            best_after = min_f[i+3] if min_f[i+3] != f[i+3][d] else min_f2[i+3]

                        if current_cost + cost_d + best_after == min_total:
                            ans.append(chr(ord('a') + d))
                            current_cost += get_dist(ord(caption[i]) - ord('a'), d)
                            curr_c = d
                            curr_len = 1
                            found = True
                            break
            if not found: return ""

    return "".join(ans)
