def minCostGoodCaption(caption: str) -> str:
    n = len(caption)
    if n < 3:
        return ""

    INF = float('inf')
    # dp[i][c_idx][state]
    # state: 0 = run length 1, 1 = run length 2, 2 = run length 3+
    dp = [[ [INF]*3 for _ in range(26)] for _ in range(n + 1)]

    # Initialization for i=1
    for c_idx in range(26):
        cost = abs(ord(caption[0]) - ord('a' + c_idx))
        dp[1][c_idx][0] = cost

    # DP Transitions
    for i in range(2, n + 1):
        for c_idx in range(26):
            cost = abs(ord(caption[i-1]) - ord('a' + c_idx))

            # State 0: current char is c_idx, run length is 1.
            # Must have come from a good caption ending in some prev_c != c_idx at i-1.
            best_prev_good = INF
            for pc in range(26):
                if pc != c_idx:
                    if dp[i-1][pc][2] < best_prev_good:
                        best_prev_good = dp[i-1][pc][2]
            # Special case: if i=1, it's not a good caption yet, but we handled that.
            # For i > 1, to have run length 1 at index i, the prefix at i-1 must be "good".
            dp[i][c_idx][0] = best_prev_good + cost if best_prev_good != INF else INF

            # State 1: current char is c_idx, run length is 2.
            # Must have come from state 0 at i-1 with the same character.
            dp[i][c_idx][1] = dp[i-1][c_idx][0] + cost if dp[i-1][c_idx][0] != INF else INF

            # State 2: current char is c_idx, run length is 3+.
            # Must have come from state 1 or state 2 at i-1 with the same character.
            prev_best = min(dp[i-1][c_idx][1], dp[i-1][c_idx][2])
            dp[i][c_idx][2] = prev_best + cost if prev_best != INF else INF

    min_total_cost = INF
    for c_idx in range(26):
        if dp[n][c_idx][2] < min_total_cost:
            min_total_cost = dp[n][c_idx][2]

    if min_total_cost == INF:
        return ""

    # Reachability for reconstruction
    reachable = [[ [False]*3 for _ in range(26)] for _ in range(n + 1)]
    for c_idx in range(26):
        if dp[n][c_idx][2] == min_total_cost:
            reachable[n][c_idx][2] = True

    # Backward pass to fill reachable states
    for i in range(n - 1, 0, -1):
        for c_idx in range(26):
            # State 0 at i comes from state 2 of some pc != c_idx at i-1? No, the DP is forward.
            # dp[i][c_idx][s] depends on dp[i-1][...][...]
            # So reachable[i][c_idx][s] depends on reachable[i+1][...][...]

            # State 0 at i: next state is (i+1, c_idx, 1)
            if dp[i][c_idx][0] != INF and dp[i+1][c_idx][1] == dp[i][c_idx][0] + abs(ord(caption[i]) - ord('a' + c_idx)):
                if reachable[i+1][c_idx][1]: reachable[i][c_idx][0] = True

            # State 1 at i: next state is (i+1, c_idx, 2)
            if dp[i][c_idx][1] != INF and dp[i+1][c_idx][2] == dp[i][c_idx][1] + abs(ord(caption[i]) - ord('a' + c_idx)):
                if reachable[i+1][c_idx][2]: reachable[i][c_idx][1] = True

            # State 2 at i: next state is (i+1, c_idx, 2) OR (i+1, next_c, 0) where next_c != c_idx
            if dp[i][c_idx][2] != INF:
                # Same char transition
                cost_same = abs(ord(caption[i]) - ord('a' + c_idx))
                if dp[i+1][c_idx][2] == dp[i][c_idx][2] + cost_same:
                    if reachable[i+1][c_idx][2]: reachable[i][c_idx][2] = True
                # Different char transition
                for next_c in range(26):
                    if next_c != c_idx:
                        cost_diff = abs(ord(caption[i]) - ord('a' + next_c))
                        if dp[i+1][next_c][0] == dp[i][c_idx][2] + cost_diff:
                            if reachable[i+1][next_c][0]: reachable[i][c_idx][2] = True

    # Lexicographical reconstruction
    res = []
    curr_c = -1
    curr_s = -1

    # Find initial state at i=1
    for c_idx in range(26):
        for s in range(3):
            if reachable[1][c_idx][s]:
                res.append(chr(ord('a') + c_idx))
                curr_c = c_idx
                curr_s = s
                break
        if curr_c != -1: break

    for i in range(2, n + 1):
        found = False
        for next_c in range(26):
            cost = abs(ord(caption[i-1]) - ord('a' + next_c))
            for next_s in range(3):
                if reachable[i][next_c][next_s]:
                    is_valid = False
                    if next_c == curr_c:
                        if curr_s == 0 and next_s == 1: is_valid = True
                        elif curr_s == 1 and next_s == 2: is_valid = True
                        elif curr_s == 2 and next_s == 2: is_valid = True
                    else: # next_c != curr_c
                        if curr_s == 2 and next_s == 0: is_valid = True

                    if is_valid and dp[i][next_c][next_s] == dp[i-1][curr_c][curr_s] + cost:
                        res.append(chr(ord('a') + next_c))
                        curr_c = next_c
                        curr_s = next_s
                        found = True
                        break
            if found: break

    return "".join(res)

