def minStartingIndex(s: str, pattern: str) -> int:
    n = len(s)
    m = len(pattern)

    if m > n:
        return -1

    for i in range(n - m + 1):
        diff_count = 0
        # Optimization: Stop early if more than one difference is found
        for j in range(m):
            if s[i + j] != pattern[j]:
                diff_count += 1
                if diff_count > 1:
                    break

        if diff_count <= 1:
            return i

    return -1
