def countOfSubstrings(word: str, k: int) -> int:
    vowels = set("aeiou")
    n = len(word)
    count = 0

    # 因為字串長度只有 250，使用 O(n^2) 的雙層迴圈即可通過。
    for i in range(n):
        current_vowels = set()
        consonants = 0
        for j in range(i, n):
            char = word[j]
            if char in vowels:
                current_vowels.add(char)
            else:
                consonants += 1

            # 如果子字串已經包含所有元音且子音數量等於 k，計數加 1
            if len(current_vowels) == 5 and consonants == k:
                count += 1
            # 如果子音已經超過 k，後續的子字串也不可能符合條件，可提前跳出
            elif consonants > k:
                break

    return count
