    for i in range(n):
        current_vowels = set()
        consonant_count = 0
        for j in range(i, n):
            char = word[j]
            if char in vowels:
                current_vowels.add(char)
            else:
                consonant_count += 1

            # 如果子字串包含所有元音且恰好有 k 個輔音，計數加一
            if len(current_vowels) == 5 and consonant_count == k:
                count += 1
            # 如果輔音數量已經超過 k，則此起始點 i 的後續子字串都不可能符合條件
            if consonant_count > k:
                break

    return count
